  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Page Hero (smaller) */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, #1a0000 0%, var(--bg) 50%, #1a0a0a 100%);
