  line-height: 1.1;
  margin-bottom: 16px;
}

.page-hero p {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 550px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Responsive */
@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
