*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --bg: #111;
  --bg-card: #1a1a1a;
  --bg-elevated: #222;
  --text: #fff;
  --text-muted: #aaa;
  --text-dim: #777;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 0.3s ease;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Top Promo Bar */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 20px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
}

.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 600;
}

/* Navigation */
.nav {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 70px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
}

.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}

.nav-cta {
  display: flex;
  gap: 12px;
  align-items: center;
}

.nav-cta .btn-sm {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 8px 20px;
  border: 1px solid var(--red);
  color: var(--text);
  transition: all var(--transition);
  cursor: pointer;
  background: transparent;
}

.nav-cta .btn-sm:hover {
  background: var(--red);
}

.nav-cta .btn-sm.filled {
  background: var(--red);
  border-color: var(--red);
}

.nav-cta .btn-sm.filled:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  font-size: 1.5rem;
  cursor: pointer;
  padding: 8px;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(135deg, #1a0000 0%, var(--bg) 40%, #1a0a0a 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230, 57, 70, 0.08) 0%, transparent 70%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  line-height: 1.1;
  margin-bottom: 20px;
}

.hero h1 .highlight {
  color: var(--red);
}

.hero p {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 16px 40px;
  border: 2px solid var(--red);
  transition: all var(--transition);
  cursor: pointer;
  text-align: center;
}

.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: #fff;
  border-color: #fff;
}

.btn-outline:hover {
  background: #fff;
  color: var(--bg);
  transform: translateY(-2px);
}

.btn-large {
  padding: 20px 56px;
  font-size: 1.15rem;
  letter-spacing: 3px;
}

/* Section Styles */
.section {
  padding: 100px 24px;
}

.section-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-title {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 20px;
}

.section-subtitle {
  text-align: center;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto 60px;
  font-size: 1.05rem;
  line-height: 1.7;
}

/* Community Promo */
.community-promo {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0a0a 100%);
}

.community-promo .section-inner {
  text-align: center;
}

.community-promo .section-title .highlight {
  color: var(--red);
}

/* Two Ways Section */
.two-ways {
  background: var(--bg);
}

.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 40px;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  padding: 48px 40px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition);
}

.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: var(--red);
}

.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--red);
}

.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 1rem;
}

/* Studio Experience */
.studio-experience {
  background: linear-gradient(180deg, #1a0a0a 0%, var(--bg) 100%);
  text-align: center;
}

.studio-experience .section-inner {
  position: relative;
}

.studio-experience .section-title {
  margin-bottom: 20px;
}

.studio-cta-text {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--text-muted);
  margin-top: 40px;
  margin-bottom: 24px;
}

/* Free Trial CTA */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 24px;
  position: relative;
  overflow: hidden;
}

.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,0,0,0.2) 0%, transparent 50%, rgba(0,0,0,0.2) 100%);
}

.free-trial .section-inner {
  position: relative;
  z-index: 2;
}

.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 32px;
  color: #fff;
}

.free-trial .btn {
  background: #fff;
  color: var(--red);
  border-color: #fff;
  font-size: 1.1rem;
  padding: 18px 48px;
}

.free-trial .btn:hover {
  background: var(--bg);
  color: #fff;
  border-color: var(--bg);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.3);
}

/* Carousel */
.carousel-section {
  background: var(--bg);
  padding: 80px 0;
  overflow: hidden;
}

.carousel-section .section-title {
  padding: 0 24px;
  margin-bottom: 48px;
}

.carousel-container {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--text-dim);
  background: linear-gradient(135deg, var(--bg-card) 0%, #2a1015 100%);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 50px;
  height: 50px;
  background: rgba(230, 57, 70, 0.9);
  border: none;
  color: #fff;
  font-size: 1.2rem;
  cursor: pointer;
  z-index: 10;
  transition: all var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-btn:hover {
  background: var(--red);
  box-shadow: 0 4px 15px var(--red-glow);
}

.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--text-dim);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--red);
  transform: scale(1.3);
}

/* Newsletter */
.newsletter {
  background: var(--bg-card);
  padding: 80px 24px;
  text-align: center;
}

.newsletter .section-inner {
  max-width: 600px;
}

.newsletter h2 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--text-muted);
  margin-bottom: 32px;
  font-size: 0.95rem;
}

.newsletter-form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}

.newsletter-form input:focus {
  border-color: var(--red);
}

.newsletter-form input::placeholder {
  color: var(--text-dim);
}

.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  border: 1px solid var(--red);
  color: #fff;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.newsletter-form button:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
}

.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}

.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: var(--red); }

/* Footer */
.footer {
  background: #0a0a0a;
  padding: 80px 24px 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 60px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-muted);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--text);
}

.footer-country {
  margin-top: 16px;
}

.footer-country select {
  background: var(--bg);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  cursor: pointer;
  width: 100%;
  max-width: 200px;
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  color: var(--text-dim);
  font-size: 0.8rem;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: var(--text-dim);
  font-size: 1.1rem;
  transition: color var(--transition);
}

.footer-social a:hover {
  color: var(--red);
}

/* Method Overview */
.method-overview {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0a0a 100%);
}

.method-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
