.method-text h2 {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 24px;
}

.method-text h2 .highlight {
  color: var(--red);
}

.method-text p {
  color: var(--text-muted);
