}

.method-visual {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card) 0%, #2a1015 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(230, 57, 70, 0.2);
