  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.schedule-table tbody tr {
  transition: background var(--transition);
}

.schedule-table tbody tr:hover {
  background: rgba(230, 57, 70, 0.05);
}

.schedule-table .day {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
}

.schedule-table .focus {
  color: var(--text-muted);
}

/* Floor/Treadmill Toggle */
.floor-tread {
  background: linear-gradient(180deg, #1a0a0a 0%, var(--bg) 100%);
}

.toggle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 48px;
}

.toggle-btn-group {
  display: flex;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.1);
  overflow: hidden;
}

.toggle-btn {
  padding: 16px 40px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn.active {
  background: var(--red);
  color: #fff;
}

.toggle-btn:hover:not(.active) {
  color: var(--text);
  background: rgba(255, 255, 255, 0.05);
}

.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.toggle-panel {
  display: none;
}

.toggle-panel.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-panel h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  margin-bottom: 16px;
}

.toggle-panel p {
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* CTA Book */
.cta-book {
  text-align: center;
  background: var(--bg);
}

.cta-book .section-title {
  margin-bottom: 12px;
}

.cta-book p {
  color: var(--text-muted);
  margin-bottom: 32px;
  font-size: 1.05rem;
}

/* Instructor Page */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.filter-btn:hover {
  border-color: var(--red);
  color: var(--text);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 28px;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
}

.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated) 0%, #2a1015 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.instructor-initials {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.5;
  text-transform: uppercase;
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.instructor-info .location {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 16px;
}

.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--red);
  transition: color var(--transition);
}

.instructor-info .book-link:hover {
  color: #fff;
}

.instructor-card.hidden {
  display: none;
}

/* FAQ Accordion */
.faq-section {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 24px 0;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}

.faq-question:hover {
  color: var(--red);
}

.faq-icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 1rem;
}

/* Digital Platform Features */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.05);
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
}

.feature-card:hover {
  border-color: rgba(230, 57, 70, 0.3);
  transform: translateY(-2px);
}

.feature-card .feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230, 57, 70, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.2rem;
  color: var(--red);
}

.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Page Hero (smaller) */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, #1a0000 0%, var(--bg) 50%, #1a0a0a 100%);
  position: relative;
}

.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230, 57, 70, 0.06) 0%, transparent 70%);
}

.page-hero .hero-content {
  max-width: 700px;
}

.page-hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  line-height: 1.1;
  margin-bottom: 16px;
}

.page-hero p {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 550px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Responsive */
@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .method-content {
    grid-template-columns: 1fr;
  }

  .nav-links {
    display: none;
    position: fixed;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17, 17, 17, 0.98);
    flex-direction: column;
    padding: 24px;
    gap: 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  }

  .nav-links.open {
    display: flex;
  }

  .nav-toggle {
    display: block;
  }

  .nav-cta {
    display: none;
  }

  .hero h1 {
    font-size: clamp(2rem, 5vw, 3rem);
  }
}

@media (max-width: 600px) {
  .section {
    padding: 60px 16px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .newsletter-form input,
  .newsletter-form button {
    width: 100%;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .btn {
    width: 100%;
    max-width: 300px;
  }

  .filter-controls {
    gap: 8px;
  }

  .filter-btn {
    padding: 8px 16px;
    font-size: 0.75rem;
  }

  .toggle-btn {
    padding: 12px 24px;
    font-size: 0.85rem;
  }

  .schedule-table thead th,
  .schedule-table tbody td {
    padding: 14px 16px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}
